    CONSTRAINT ck_suppression_list__retention_period_days CHECK (retention_period_days >= 0),
    CONSTRAINT ck_suppression_list__scope_level CHECK (scope_level IN ('global', 'advertiser', 'campaign', 'line_item')),
    CONSTRAINT ck_suppression_list__suppression_type CHECK (suppression_type IN ('converted_customer', 'opted_out', 'frequency_capped', 'competitor_employee', 'brand_safety', 'fraud_prevention')),
    CONSTRAINT ck_suppression_list__effective_end_date_ge_effective_start_date CHECK (effective_end_date >= effective_start_date)
);
